+}
+
+export function criarAtividade(corpo) {
+  return chamar('/atividades', { metodo: 'POST', corpo });
+}
+
+export function inscrever(atividadeId) {
+  return chamar(`/atividades/${encodeURIComponent(atividadeId)}/inscricoes`, { metodo: 'POST' });
+}
+
