+  return chamar(`/inscricoes${sufixo ? `?${sufixo}` : ''}`);
+}
+
+export function obterInscricao(id) {
+  return chamar(`/inscricoes/${encodeURIComponent(id)}`);
+}
+
+export function cancelarInscricao(id) {
