+export function registrarPresenca(encontroId, { codigo, lidoEm } = {}) {
+  return chamar(`/encontros/${encodeURIComponent(encontroId)}/presencas`, {
+    metodo: 'POST',
+    corpo: { codigo, lidoEm },
+  });
+}
