+                  <button type="button" onClick={() => aoSelecionarEncontro(encontro.id)}>
+                    Presença por QR
+                  </button>
+                )}
+              </li>
+            ))}
+          </ul>
+          <div>
+            <button type="button" onClick={handleInscrever}>
+              Inscrever
+            </button>
+            <button type="button" onClick={handleCancelar}>
+              Cancelar inscrição
+            </button>
